import React, { useState } from 'react';
import { Plus, Search, Edit, Trash2, FolderOpen, ChevronRight, X } from 'lucide-react';
import { useNotification } from '../components/Notification';
import { useData } from '../contexts/DataContext';
import Modal from '../components/Modal';

export default function Categories() {
  const { success, warning, error } = useNotification();
  // 原来靠 props 拿 categories 与保存/删除回调，现在页面自取 Context
  const { categories, createCategory, updateCategory, deleteCategory } = useData();
  const [searchQuery, setSearchQuery] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', message: '', onConfirm: null });
  const [formData, setFormData] = useState({
    name: '',
    slug: '',
    description: '',
    parent: null,
  });

  const filteredCategories = categories.filter((cat) => {
    return cat.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
           cat.slug.toLowerCase().includes(searchQuery.toLowerCase()) ||
           (cat.description && cat.description.toLowerCase().includes(searchQuery.toLowerCase()));
  });

  // 构建层级结构
  const rootCategories = filteredCategories.filter(cat => cat.parent === null);

  const getChildren = (parentId) => {
    return filteredCategories.filter(cat => cat.parent === parentId);
  };

  const getParentName = (parentId) => {
    const parent = categories.find(cat => cat.id === parentId);
    return parent ? parent.name : '-';
  };

  const handleOpenModal = (category = null) => {
    if (category) {
      setEditingCategory(category);
      setFormData({
        name: category.name,
        slug: category.slug,
        description: category.description || '',
        parent: category.parent,
      });
    } else {
      setEditingCategory(null);
      setFormData({
        name: '',
        slug: '',
        description: '',
        parent: null,
      });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setEditingCategory(null);
    setFormData({ name: '', slug: '', description: '', parent: null });
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    // 自动生成 slug
    if (name === 'name' && !editingCategory) {
      const slug = value.toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]/g, '-').replace(/-+/g, '-');
      setFormData(prev => ({ ...prev, slug }));
    }
  };

  // 原来保存走 props.onSave 回调，现在页面自取 Context 的语义化方法
  const handleSave = async (data) => {
    try {
      if (data.id) {
        await updateCategory(data.id, data);
        success('分类更新成功');
      } else {
        await createCategory(data);
        success('分类创建成功');
      }
    } catch (err) {
      error(err.message || '保存分类失败');
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!formData.name.trim()) {
      warning('请输入分类名称');
      return;
    }

    if (!formData.slug.trim()) {
      warning('请输入分类slug');
      return;
    }

    // 检查 slug 是否重复
    const existingSlug = categories.find(cat => cat.slug === formData.slug && cat.id !== editingCategory?.id);
    if (existingSlug) {
      warning('该slug已存在，请使用不同的slug');
      return;
    }

    if (editingCategory) {
      handleSave({ ...editingCategory, ...formData });
    } else {
      handleSave(formData);
    }

    handleCloseModal();
  };

  const handleDelete = (category) => {
    if (category.count > 0) {
      warning(`该分类下有 ${category.count} 篇文章，无法删除`);
      return;
    }

    const children = categories.filter(cat => cat.parent === category.id);
    if (children.length > 0) {
      warning('该分类下有子分类，请先删除子分类');
      return;
    }

    setConfirmModal({
      isOpen: true,
      title: '确认删除',
      message: `确定要删除分类"${category.name}"吗？`,
      // 原来删除走 props.onDelete 回调，现在页面自取 Context 的 deleteCategory
      onConfirm: async () => {
        try {
          await deleteCategory(category.id);
          success('分类删除成功');
        } catch (err) {
          error(err.message || '删除分类失败');
        }
      }
    });
  };

  const renderCategoryRow = (category, level = 0) => {
    const children = getChildren(category.id);

    return (
      <tr key={category.id} className="hover:bg-gray-50 dark:hover:bg-gray-700">
        <td className="px-4 py-4">
          <div className="flex items-center gap-2" style={{ paddingLeft: `${level * 24}px` }}>
            {level > 0 && <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />}
            <FolderOpen className="w-5 h-5 text-blue-500 flex-shrink-0" />
            <div>
              <span className="font-medium text-gray-900 dark:text-white">{category.name}</span>
              {level > 0 && (
                <span className="ml-2 text-xs text-gray-400">(子分类)</span>
              )}
            </div>
          </div>
        </td>
        <td className="px-4 py-4 text-sm text-gray-600 dark:text-gray-400 font-mono">{category.slug}</td>
        <td className="px-4 py-4 text-sm text-gray-500 dark:text-gray-400 max-w-xs truncate">{category.description || '-'}</td>
        <td className="px-4 py-4 text-sm text-gray-600 dark:text-gray-400">
          {category.parent ? getParentName(category.parent) : '-'}
        </td>
        <td className="px-4 py-4">
          <span className="px-2 py-1 text-xs font-medium bg-blue-100 dark:bg-blue-900 text-blue-700 dark:text-blue-300 rounded-full">
            {category.count} 篇
          </span>
        </td>
        <td className="px-4 py-4">
          <div className="flex items-center justify-end gap-2">
            <button
              onClick={() => handleOpenModal(category)}
              className="p-2 text-gray-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900 rounded-lg transition-colors"
            >
              <Edit className="w-4 h-4" />
            </button>
            <button
              onClick={() => handleDelete(category)}
              className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900 rounded-lg transition-colors"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        </td>
      </tr>
    );
  };

  const renderTree = (parentId = null, level = 0) => {
    const items = parentId === null 
      ? filteredCategories.filter(cat => cat.parent === null)
      : filteredCategories.filter(cat => cat.parent === parentId);

    return items.map(category => (
      <React.Fragment key={category.id}>
        {renderCategoryRow(category, level)}
        {renderTree(category.id, level + 1)}
      </React.Fragment>
    ));
  };

  return (
    <>
      <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">分类管理</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">管理您网站的文章分类</p>
        </div>
        <button
          onClick={() => handleOpenModal()}
          className="px-4 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors flex items-center gap-2"
        >
          <Plus className="w-4 h-4" />
          新建分类
        </button>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700">
          <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="搜索分类..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="bg-gray-50 dark:bg-gray-700">
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">名称</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">Slug</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">描述</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">父分类</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">文章数</th>
                <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {renderTree()}
            </tbody>
          </table>
        </div>

        {filteredCategories.length === 0 && (
          <div className="py-12 text-center">
            <FolderOpen className="w-12 h-12 text-gray-300 mx-auto mb-4" />
            <p className="text-gray-500 dark:text-gray-400">没有找到匹配的分类</p>
          </div>
        )}
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md mx-4">
            <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                {editingCategory ? '编辑分类' : '新建分类'}
              </h2>
              <button
                onClick={handleCloseModal}
                className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-4 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  名称 *
                </label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  placeholder="输入分类名称"
                  className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Slug *
                </label>
                <input
                  type="text"
                  name="slug"
                  value={formData.slug}
                  onChange={handleInputChange}
                  placeholder="category-slug"
                  className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 font-mono text-sm"
                />
                <p className="mt-1 text-xs text-gray-500">URL友好的标识符</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  描述
                </label>
                <textarea
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  placeholder="输入分类描述（可选）"
                  rows={3}
                  className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  父分类
                </label>
                <select
                  name="parent"
                  value={formData.parent || ''}
                  onChange={handleInputChange}
                  className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">无（作为一级分类）</option>
                  {categories
                    .filter(cat => !editingCategory || cat.id !== editingCategory.id)
                    .map(cat => (
                      <option key={cat.id} value={cat.id}>{cat.name}</option>
                    ))
                  }
                </select>
                <p className="mt-1 text-xs text-gray-500">选择上级分类创建子分类</p>
              </div>

              <div className="flex justify-end gap-3 pt-4">
                <button
                  type="button"
                  onClick={handleCloseModal}
                  className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg font-medium transition-colors"
                >
                  取消
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors"
                >
                  {editingCategory ? '保存修改' : '创建分类'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>

    <Modal
      isOpen={confirmModal.isOpen}
      onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
      title={confirmModal.title}
      message={confirmModal.message}
      type="confirm"
      onConfirm={confirmModal.onConfirm}
    />
    </>
  );
}

import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Search, Check, Trash2, Reply, MessageSquare, User, Mail, AlertTriangle } from 'lucide-react';
import { useData } from '../contexts/DataContext';
import { useNotification } from '../components/Notification';
import Modal from '../components/Modal';

export default function Comments() {
  const { comments, posts, deleteComment, updateCommentStatus, createComment } = useData();
  const { warning, success, error } = useNotification();
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedComments, setSelectedComments] = useState([]);
  const [replyingTo, setReplyingTo] = useState(null);
  const [replyForm, setReplyForm] = useState({ author: '', email: '', content: '' });
  const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', message: '', onConfirm: null });

  const getCommentField = (comment, field) => {
    const mapping = {
      postId: comment.post_id,
      parentId: comment.parent_id,
      createdAt: comment.created_at,
    };
    return mapping[field];
  };

  const tabs = [
    { id: 'all', label: '全部', count: comments.length },
    { id: 'pending', label: '待审核', count: comments.filter(c => c.status === 'pending').length },
    { id: 'approved', label: '已通过', count: comments.filter(c => c.status === 'approved').length },
    { id: 'spam', label: '垃圾评论', count: comments.filter(c => c.status === 'spam').length },
  ];

  const filteredComments = comments.filter((comment) => {
    if (activeTab !== 'all' && comment.status !== activeTab) return false;
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      return (
        comment.author.toLowerCase().includes(query) ||
        comment.email.toLowerCase().includes(query) ||
        comment.content.toLowerCase().includes(query)
      );
    }
    return true;
  }).filter(c => !getCommentField(c, 'parentId'));

  const topLevelComments = filteredComments;

  const getStatusBadge = (status) => {
    const badges = {
      pending: 'px-2 py-1 text-xs font-medium bg-yellow-100 dark:bg-yellow-900 text-yellow-700 dark:text-yellow-300 rounded-full',
      approved: 'px-2 py-1 text-xs font-medium bg-green-100 dark:bg-green-900 text-green-700 dark:text-green-300 rounded-full',
      spam: 'px-2 py-1 text-xs font-medium bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300 rounded-full',
      trash: 'px-2 py-1 text-xs font-medium bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-full',
    };
    const labels = {
      pending: '待审核',
      approved: '已通过',
      spam: '垃圾评论',
      trash: '回收站',
    };
    return <span className={badges[status]}>{labels[status]}</span>;
  };

  const getPostTitle = (postId) => {
    const post = posts.find(p => p.id === postId);
    return post ? post.title : '未知文章';
  };

  const getAvatar = (author) => {
    const initial = (author || '').charAt(0).toUpperCase() || '?';
    return (
      <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-500 rounded-full flex items-center justify-center text-white font-medium">
        {initial}
      </div>
    );
  };

  const handleSelect = (id) => {
    setSelectedComments(prev =>
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleApprove = (id) => {
    updateCommentStatus(id, 'approved');
  };

  const handleSpam = (id) => {
    updateCommentStatus(id, 'spam');
  };

  const handleTrash = (id) => {
    setConfirmModal({
      isOpen: true,
      title: '确认移到回收站',
      message: '确定要将这条评论移到回收站吗？',
      onConfirm: () => updateCommentStatus(id, 'trash')
    });
  };

  const handleDelete = (id) => {
    setConfirmModal({
      isOpen: true,
      title: '确认删除',
      message: '确定要永久删除这条评论及其回复吗？',
      onConfirm: () => deleteComment(id)
    });
  };

  const handleBulkApprove = () => {
    selectedComments.forEach(id => updateCommentStatus(id, 'approved'));
    setSelectedComments([]);
  };

  const handleBulkDelete = () => {
    setConfirmModal({
      isOpen: true,
      title: '确认批量删除',
      message: `确定要永久删除选中的 ${selectedComments.length} 条评论吗？`,
      onConfirm: () => {
        selectedComments.forEach(id => deleteComment(id));
        setSelectedComments([]);
      }
    });
  };

  const handleReply = (commentId) => {
    setReplyingTo(commentId);
    setReplyForm({ author: '', email: '', content: '' });
  };

  const handleReplySubmit = (e) => {
    e.preventDefault();
    if (!replyForm.author || !replyForm.email || !replyForm.content) {
      warning('请填写所有字段');
      return;
    }
    const parentComment = comments.find(c => c.id === replyingTo);
    createComment({
      postId: parentComment ? getCommentField(parentComment, 'postId') || null : null,
      parentId: replyingTo,
      author: replyForm.author,
      email: replyForm.email,
      content: replyForm.content,
    });
    setReplyingTo(null);
    setReplyForm({ author: '', email: '', content: '' });
  };

  const cancelReply = () => {
    setReplyingTo(null);
    setReplyForm({ author: '', email: '', content: '' });
  };

  const renderReplies = (parentId, level = 1) => {
    const replies = comments.filter(c => getCommentField(c, 'parentId') === parentId);
    if (replies.length === 0) return null;

    return (
      <div className={`mt-4 space-y-4 ${level > 1 ? 'ml-8 border-l-2 border-gray-200 dark:border-gray-700 pl-4' : ''}`}>
        {replies.map(reply => (
          <div key={reply.id} className="relative">
            <div className="flex gap-3">
              {getAvatar(reply.author)}
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-medium text-gray-900 dark:text-white">{reply.author}</span>
                  <span className="text-sm text-gray-500 dark:text-gray-400">{reply.email}</span>
                  {getStatusBadge(reply.status)}
                </div>
                <p className="text-gray-600 dark:text-gray-300 mb-2">{reply.content}</p>
                <div className="flex items-center gap-4 text-sm">
                  <span className="text-gray-400">{getCommentField(reply, 'createdAt')}</span>
                  {reply.status === 'approved' && (
                    <button
                      onClick={() => handleReply(reply.id)}
                      className="flex items-center gap-1 text-blue-500 hover:text-blue-600"
                    >
                      <Reply className="w-3 h-3" />
                      回复
                    </button>
                  )}
                  <button
                    onClick={() => handleDelete(reply.id)}
                    className="flex items-center gap-1 text-red-500 hover:text-red-600"
                  >
                    <Trash2 className="w-3 h-3" />
                    删除
                  </button>
                </div>
              </div>
            </div>
            {replyingTo === reply.id && (
              <form onSubmit={handleReplySubmit} className="mt-4 p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                <div className="grid grid-cols-2 gap-4 mb-4">
                  <input
                    type="text"
                    placeholder="昵称"
                    value={replyForm.author}
                    onChange={e => setReplyForm({ ...replyForm, author: e.target.value })}
                    className="px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                  />
                  <input
                    type="email"
                    placeholder="邮箱"
                    value={replyForm.email}
                    onChange={e => setReplyForm({ ...replyForm, email: e.target.value })}
                    className="px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                  />
                </div>
                <textarea
                  placeholder="回复内容..."
                  value={replyForm.content}
                  onChange={e => setReplyForm({ ...replyForm, content: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white mb-4"
                  rows={3}
                />
                <div className="flex gap-2">
                  <button
                    type="submit"
                    className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
                  >
                    提交回复
                  </button>
                  <button
                    type="button"
                    onClick={cancelReply}
                    className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-200 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-500"
                  >
                    取消
                  </button>
                </div>
              </form>
            )}
            {renderReplies(reply.id, level + 1)}
          </div>
        ))}
      </div>
    );
  };

  return (
    <>
      <div className="p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">评论管理</h1>
        <p className="text-gray-500 dark:text-gray-400 mt-1">管理用户评论和回复</p>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 mb-6 border-b border-gray-200 dark:border-gray-700">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => {
              setActiveTab(tab.id);
              setSelectedComments([]);
            }}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === tab.id
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200'
            }`}
          >
            {tab.label}
            {tab.count > 0 && (
              <span className="ml-2 px-2 py-0.5 text-xs rounded-full bg-gray-100 dark:bg-gray-700">
                {tab.count}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Search */}
      <div className="mb-6">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="搜索评论..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
      </div>

      {/* Bulk Actions */}
      {selectedComments.length > 0 && (
        <div className="mb-4 p-3 bg-blue-50 dark:bg-blue-900/30 rounded-lg flex items-center justify-between">
          <span className="text-sm text-blue-700 dark:text-blue-300">
            已选择 {selectedComments.length} 条评论
          </span>
          <div className="flex gap-2">
            <button
              onClick={handleBulkApprove}
              className="px-3 py-1 text-sm bg-green-500 text-white rounded-lg hover:bg-green-600"
            >
              批量通过
            </button>
            <button
              onClick={handleBulkDelete}
              className="px-3 py-1 text-sm bg-red-500 text-white rounded-lg hover:bg-red-600"
            >
              批量删除
            </button>
          </div>
        </div>
      )}

      {/* Comments List */}
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        {topLevelComments.length === 0 ? (
          <div className="py-12 text-center">
            <MessageSquare className="w-12 h-12 mx-auto text-gray-300 dark:text-gray-600 mb-4" />
            <p className="text-gray-500 dark:text-gray-400">没有找到评论</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-100 dark:divide-gray-700">
            {topLevelComments.map(comment => {
              const replyCount = comments.filter(c => getCommentField(c, 'parentId') === comment.id).length;
              return (
                <div key={comment.id} className="p-6">
                  <div className="flex gap-3">
                    <input
                      type="checkbox"
                      checked={selectedComments.includes(comment.id)}
                      onChange={() => handleSelect(comment.id)}
                      className="mt-1 w-4 h-4 text-blue-500 rounded border-gray-300 dark:border-gray-600"
                    />
                    {getAvatar(comment.author)}
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-medium text-gray-900 dark:text-white">{comment.author}</span>
                        <span className="text-sm text-gray-500 dark:text-gray-400 flex items-center gap-1">
                          <Mail className="w-3 h-3" />
                          {comment.email}
                        </span>
                        {getStatusBadge(comment.status)}
                        {replyCount > 0 && (
                          <span className="text-xs text-gray-400 flex items-center gap-1">
                            <MessageSquare className="w-3 h-3" />
                            {replyCount} 条回复
                          </span>
                        )}
                      </div>
                      <p className="text-gray-600 dark:text-gray-300 mb-2">{comment.content}</p>
                      <div className="flex items-center gap-4 text-sm">
                        <Link
                          to={`/posts/${getCommentField(comment, 'postId')}`}
                          className="text-blue-500 hover:text-blue-600 flex items-center gap-1"
                        >
                          <User className="w-3 h-3" />
                          {getPostTitle(getCommentField(comment, 'postId'))}
                        </Link>
                        <span className="text-gray-400">{getCommentField(comment, 'createdAt')}</span>
                      </div>
                      <div className="flex items-center gap-2 mt-3">
                        {comment.status === 'pending' && (
                          <>
                            <button
                              onClick={() => handleApprove(comment.id)}
                              className="flex items-center gap-1 px-3 py-1 text-sm bg-green-500 text-white rounded-lg hover:bg-green-600"
                            >
                              <Check className="w-3 h-3" />
                              通过
                            </button>
                            <button
                              onClick={() => handleSpam(comment.id)}
                              className="flex items-center gap-1 px-3 py-1 text-sm bg-yellow-500 text-white rounded-lg hover:bg-yellow-600"
                            >
                              <AlertTriangle className="w-3 h-3" />
                              标记垃圾
                            </button>
                          </>
                        )}
                        {comment.status === 'approved' && (
                          <button
                            onClick={() => handleReply(comment.id)}
                            className="flex items-center gap-1 px-3 py-1 text-sm bg-blue-500 text-white rounded-lg hover:bg-blue-600"
                          >
                            <Reply className="w-3 h-3" />
                            回复
                          </button>
                        )}
                        <button
                          onClick={() => handleTrash(comment.id)}
                          className="flex items-center gap-1 px-3 py-1 text-sm bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-200 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-500"
                        >
                          <Trash2 className="w-3 h-3" />
                          移至回收站
                        </button>
                        <button
                          onClick={() => handleDelete(comment.id)}
                          className="flex items-center gap-1 px-3 py-1 text-sm bg-red-100 dark:bg-red-900 text-red-600 dark:text-red-300 rounded-lg hover:bg-red-200 dark:hover:bg-red-800"
                        >
                          <Trash2 className="w-3 h-3" />
                          永久删除
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Reply Form */}
                  {replyingTo === comment.id && (
                    <form onSubmit={handleReplySubmit} className="mt-4 p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
                      <div className="grid grid-cols-2 gap-4 mb-4">
                        <input
                          type="text"
                          placeholder="昵称"
                          value={replyForm.author}
                          onChange={e => setReplyForm({ ...replyForm, author: e.target.value })}
                          className="px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        />
                        <input
                          type="email"
                          placeholder="邮箱"
                          value={replyForm.email}
                          onChange={e => setReplyForm({ ...replyForm, email: e.target.value })}
                          className="px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        />
                      </div>
                      <textarea
                        placeholder="回复内容..."
                        value={replyForm.content}
                        onChange={e => setReplyForm({ ...replyForm, content: e.target.value })}
                        className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white mb-4"
                        rows={3}
                      />
                      <div className="flex gap-2">
                        <button
                          type="submit"
                          className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
                        >
                          提交回复
                        </button>
                        <button
                          type="button"
                          onClick={cancelReply}
                          className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-200 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-500"
                        >
                          取消
                        </button>
                      </div>
                    </form>
                  )}

                  {/* Nested Replies */}
                  {renderReplies(comment.id)}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>

    <Modal
      isOpen={confirmModal.isOpen}
      onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
      title={confirmModal.title}
      message={confirmModal.message}
      type="confirm"
      onConfirm={confirmModal.onConfirm}
    />
    </>
  );
}

