export default function CustomCSS() {
  const { success } = useNotification();
  const [activeTab, setActiveTab] = useState('css');
  const [customCSS, setCustomCSS] = useState('');
  const [customJS, setCustomJS] = useState('');
  const [customHead, setCustomHead] = useState('');
  const [hasChanges, setHasChanges] = useState(false);
  const [saved, setSaved] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const [cssError, setCssError] = useState('');
  const [copiedSnippet, setCopiedSnippet] = useState('');
  const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', message: '', onConfirm: null });

  useEffect(() => {
    const savedCSS = localStorage.getItem('happyhome_custom_css') || '';
    const savedJS = localStorage.getItem('happyhome_custom_js') || '';
    const savedHead = localStorage.getItem('happyhome_custom_head') || '';
    setCustomCSS(savedCSS);
    setCustomJS(savedJS);
    setCustomHead(savedHead);
  }, []);

  const handleCSSChange = (value) => {
    setCustomCSS(value);
    setHasChanges(true);
    validateCSS(value);
  };

  const handleJSChange = (value) => {
    setCustomJS(value);
    setHasChanges(true);
  };

  const handleHeadChange = (value) => {
    setCustomHead(value);
    setHasChanges(true);
  };

  const validateCSS = (css) => {
    if (!css.trim()) {
      setCssError('');
      return true;
    }

    const openBraces = (css.match(/{/g) || []).length;
    const closeBraces = (css.match(/}/g) || []).length;

    if (openBraces !== closeBraces) {
      setCssError('CSS 语法错误：大括号不匹配');
      return false;
    }

    const openParens = (css.match(/\(/g) || []).length;
    const closeParens = (css.match(/\)/g) || []).length;

    if (openParens !== closeParens) {
      setCssError('CSS 语法错误：括号不匹配');
      return false;
    }

    setCssError('');
    return true;
  };

  const handleSave = () => {
    localStorage.setItem('happyhome_custom_css', customCSS);
    localStorage.setItem('happyhome_custom_js', customJS);
    localStorage.setItem('happyhome_custom_head', customHead);
    setHasChanges(false);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const handleReset = () => {
    setConfirmModal({
      isOpen: true,
      title: '确认重置',
      message: '确定要重置所有自定义代码吗？',
      onConfirm: () => {
        setCustomCSS('');
        setCustomJS('');
        setCustomHead('');
        localStorage.removeItem('happyhome_custom_css');
        localStorage.removeItem('happyhome_custom_js');
        localStorage.removeItem('happyhome_custom_head');
        setHasChanges(false);
        success('已重置所有自定义代码');
      }
    });
  };

  const handleInsertSnippet = (snippet) => {
    if (activeTab === 'css') {
      setCustomCSS(prev => prev + '\n\n' + snippet.code);
    } else if (activeTab === 'js') {
      setCustomJS(prev => prev + '\n\n' + snippet.code);
    }
    setHasChanges(true);
  };

  const handleCopySnippet = async (code, label) => {
    try {
      await navigator.clipboard.writeText(code);
      setCopiedSnippet(label);
      setTimeout(() => setCopiedSnippet(''), 2000);
    } catch (err) {
      console.error('Failed to copy');
    }
  };

  const tabs = [
    { id: 'css', label: '自定义 CSS', icon: Code },
    { id: 'js', label: '自定义 JS', icon: Terminal },
    { id: 'head', label: 'Head 代码', icon: Settings },
  ];

  const currentSnippets = activeTab === 'css' ? cssSnippets : activeTab === 'js' ? jsSnippets : [];

  return (
    <>
      <div className="p-6">
      <div className="mb-6 flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">自定义样式</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">添加自定义 CSS、JavaScript 和 Head 代码</p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={() => setShowPreview(!showPreview)}
            className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg font-medium transition-colors flex items-center gap-2"
          >
            {showPreview ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            {showPreview ? '隐藏预览' : '显示预览'}
          </button>
          <button
            onClick={handleReset}
            className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg font-medium transition-colors flex items-center gap-2"
          >
            <RotateCcw className="w-4 h-4" />
            重置
          </button>
          <button
            onClick={handleSave}
            disabled={!hasChanges}
            className={`px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2 ${
              hasChanges
                ? 'bg-blue-500 text-white hover:bg-blue-600'
                : 'bg-gray-100 dark:bg-gray-700 text-gray-400 dark:text-gray-500 cursor-not-allowed'
            }`}
          >
            <Save className="w-4 h-4" />
            {saved ? '已保存' : '保存'}
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="mb-6 border-b border-gray-200 dark:border-gray-700">
        <nav className="flex gap-4">
          {tabs.map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 pb-3 px-1 border-b-2 font-medium transition-colors ${
                  activeTab === tab.id
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
              </button>
            );
          })}
        </nav>
      </div>

      <div className={`grid gap-6 ${showPreview ? 'grid-cols-1 lg:grid-cols-2' : 'grid-cols-1'}`}>
        {/* Editor */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
          {/* Snippets Panel */}
          {currentSnippets.length > 0 && (
            <div className="p-4 border-b border-gray-100 dark:border-gray-700">
              <div className="flex items-center gap-2 mb-3">
                <FileText className="w-4 h-4 text-gray-500" />
                <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  常用代码片段
                </span>
              </div>
              <div className="flex flex-wrap gap-2">
                {currentSnippets.map((snippet) => (
                  <button
                    key={snippet.label}
                    onClick={() => handleInsertSnippet(snippet)}
                    className="px-3 py-1.5 text-xs bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors flex items-center gap-1"
                  >
                    <Code className="w-3 h-3" />
                    {snippet.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Code Editor */}
          <div className="relative">
            <textarea
              value={activeTab === 'css' ? customCSS : activeTab === 'js' ? customJS : customHead}
              onChange={(e) => {
                if (activeTab === 'css') handleCSSChange(e.target.value);
                else if (activeTab === 'js') handleJSChange(e.target.value);
                else handleHeadChange(e.target.value);
              }}
              placeholder={
                activeTab === 'css'
                  ? '/* 在这里输入自定义 CSS 代码 */\n\n例如：\nbody {\n  font-family: "Microsoft YaHei", sans-serif;\n}'
                  : activeTab === 'js'
                  ? '// 在这里输入自定义 JavaScript 代码\n\n例如：\ndocument.addEventListener("DOMContentLoaded", function() {\n  console.log("页面加载完成");\n});'
                  : '<!-- 在这里输入要添加到 <head> 的代码 -->\n\n例如：\n<link rel="stylesheet" href="external.css">\n<script src="external.js"></script>'
              }
              className={`w-full h-96 p-4 font-mono text-sm bg-gray-900 text-gray-100 resize-none focus:outline-none ${
                activeTab === 'css' ? 'font-mono' : ''
              }`}
              spellCheck={false}
            />

            {/* CSS Error */}
            {activeTab === 'css' && cssError && (
              <div className="absolute bottom-4 left-4 right-4 p-3 bg-red-500/90 text-white rounded-lg flex items-center gap-2">
                <AlertCircle className="w-4 h-4" />
                {cssError}
              </div>
            )}
          </div>

          {/* Status Bar */}
          <div className="px-4 py-2 bg-gray-50 dark:bg-gray-700/50 border-t border-gray-100 dark:border-gray-700 flex items-center justify-between">
            <div className="flex items-center gap-4 text-xs text-gray-500">
              <span>编码: UTF-8</span>
              {activeTab === 'css' && (
                <span className={cssError ? 'text-red-500' : 'text-green-500'}>
                  {cssError || '语法正确'}
                </span>
              )}
            </div>
            <div className="text-xs text-gray-500">
              {(activeTab === 'css' ? customCSS : activeTab === 'js' ? customJS : customHead).length} 字符
            </div>
          </div>
        </div>

        {/* Preview */}
        {showPreview && (
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
            <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex items-center gap-2">
              <Eye className="w-4 h-4 text-gray-500" />
              <span className="text-sm font-medium text-gray-700 dark:text-gray-300">预览</span>
            </div>
            <div className="p-4 bg-gray-50 dark:bg-gray-700/50">
              <div className="bg-white dark:bg-gray-800 p-6 rounded-xl">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
                  样式预览
                </h3>
                <p className="text-gray-600 dark:text-gray-300 mb-4">
                  这里的文本将应用您的自定义 CSS 样式。
                </p>
                <div className="flex gap-3 flex-wrap">
                  <button className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600">
                    按钮
                  </button>
                  <a href="#" className="px-4 py-2 text-blue-500 hover:text-blue-600">
                    链接
                  </a>
                </div>
                <pre className="mt-4 p-3 bg-gray-900 text-gray-100 rounded-lg text-sm overflow-x-auto">
                  <code>{"code { color: #333; }"}</code>
                </pre>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Help */}
      <div className="mt-6 bg-yellow-50 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-800 rounded-xl p-4">
        <div className="flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-yellow-600 mt-0.5" />
          <div>
            <h3 className="font-medium text-yellow-800 dark:text-yellow-200 mb-1">
              使用提示
            </h3>
            <ul className="text-sm text-yellow-700 dark:text-yellow-300 space-y-1">
              <li>• 自定义 CSS 会应用于前台页面的所有页面</li>
              <li>• 自定义 JS 会添加到页面底部 </li>
              <li>• Head 代码会添加到 &lt;head&gt; 标签内，可用于引入外部样式或脚本</li>
              <li>• 请谨慎使用，确保代码语法正确</li>
            </ul>
          </div>
        </div>
      </div>
    </div>

    <Modal
      isOpen={confirmModal.isOpen}
      onClose={() => setConfirmModal({ ...confirmModal, isOpen: false })}
      title={confirmModal.title}
      message={confirmModal.message}
      type="confirm"
      onConfirm={confirmModal.onConfirm}
    />
    </>
  );
}

import { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { User, Lock, Mail, Eye, EyeOff, LogIn, UserPlus, Zap, RefreshCw, CheckCircle } from 'lucide-react';
import { useData } from '../contexts/DataContext';
import { authAPI } from '../services/api';

export default function Login() {
  const { settings, login } = useData();
  const [isLogin, setIsLogin] = useState(true);
  const [showVerification, setShowVerification] = useState(false);
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [verificationCode, setVerificationCode] = useState('');
  const [userId, setUserId] = useState('');
  const [verificationMessage, setVerificationMessage] = useState('');
  const [resendLoading, setResendLoading] = useState(false);
  const [codeButtonText, setCodeButtonText] = useState('获取验证码');
  const [codeButtonDisabled, setCodeButtonDisabled] = useState(false);
  const [codeCountdown, setCodeCountdown] = useState(0);
  const navigate = useNavigate();
  const timerRef = useRef(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    };
  }, []);

  const handleLogin = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!username || !password) {
      setError('请输入用户名和密码');
      setLoading(false);
      return;
    }

    try {
      await login({ username, password });
      navigate('/admin');
    } catch (err) {
      setError(err.message || '登录失败');
    } finally {
      setLoading(false);
    }
  };

  const handleGetRegisterCode = async () => {
    if (!email) {
      setError('请先输入邮箱地址');
      return;
    }

    setResendLoading(true);
    try {
      const result = await authAPI.sendRegisterCode({ email });
      if (result.success) {
        setError('');
        setCodeButtonText('60秒后重新获取');
        setCodeButtonDisabled(true);
        setCodeCountdown(60);
        
        timerRef.current = setInterval(() => {
          setCodeCountdown(prev => {
            if (prev <= 1) {
              clearInterval(timerRef.current);
              timerRef.current = null;
              setCodeButtonText('获取验证码');
              setCodeButtonDisabled(false);
              return 0;
            }
            setCodeButtonText(`${prev - 1}秒后重新获取`);
            return prev - 1;
          });
        }, 1000);
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError(err.message || '发送失败');
    } finally {
      setResendLoading(false);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!username || !email || !password || !confirmPassword || !verificationCode) {
      setError('请填写所有字段，包括验证码');
      setLoading(false);
      return;
    }

    if (password !== confirmPassword) {
      setError('两次输入的密码不一致');
      setLoading(false);
      return;
    }

    if (password.length < 6) {
      setError('密码长度至少6位');
      setLoading(false);
      return;
    }

    try {
      const result = await authAPI.register({ username, email, password, code: verificationCode });
      if (result.success) {
        await login({ token: result.token });
        navigate('/admin');
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError(err.message || '注册失败');
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async (e) => {
    e.preventDefault();
    setError('');

    if (!verificationCode) {
      setError('请输入验证码');
      return;
    }

    setLoading(true);
    try {
      const result = await authAPI.verify({ userId, code: verificationCode });
      if (result.success) {
        await login({ token: result.token });
        navigate('/admin');
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError(err.message || '验证失败');
    } finally {
      setLoading(false);
    }
  };

  const handleResendVerification = async () => {
    setResendLoading(true);
    try {
      const result = await authAPI.resendVerification({ userId });
      if (result.success) {
        setVerificationMessage('验证邮件已重新发送，请查收邮箱');
        setError('');
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError(err.message || '发送失败');
    } finally {
      setResendLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl flex items-center justify-center mx-auto mb-4">
            <span className="text-white text-2xl font-bold">H</span>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">HappyHome</h1>
          <p className="text-gray-500 mt-1">欢迎回来</p>
        </div>

        <div className="flex bg-gray-100 rounded-lg p-1 mb-6">
          <button
            onClick={() => setIsLogin(true)}
            className={`flex-1 py-2 px-4 rounded-md font-medium transition-colors ${
              isLogin ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-600 hover:text-gray-800'
            }`}
          >
            登录
          </button>
          <button
            onClick={() => setIsLogin(false)}
            className={`flex-1 py-2 px-4 rounded-md font-medium transition-colors ${
              !isLogin ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-600 hover:text-gray-800'
            }`}
          >
            注册
          </button>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-red-50 text-red-700 rounded-lg text-sm">
            {error}
          </div>
        )}

        {isLogin ? (
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">用户名</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="请输入用户名"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">密码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="请输入密码"
                  className="w-full pl-10 pr-12 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            <button
              type="submit"
              className="w-full py-3 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors flex items-center justify-center gap-2"
            >
              <LogIn className="w-5 h-5" />
              登录
            </button>

            {settings?.showQuickLoginButton !== false && (
              <button
                type="button"
                onClick={() => {
                  setUsername('admin');
                  setPassword('admin123');
                }}
                className="w-full py-3 mt-3 bg-gradient-to-r from-orange-500 to-red-500 text-white rounded-lg font-medium hover:from-orange-600 hover:to-red-600 transition-all flex items-center justify-center gap-2"
              >
                <Zap className="w-5 h-5" />
                快速登录管理员
              </button>
            )}
          </form>
        ) : (
          <form onSubmit={handleRegister} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">用户名</label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="请输入用户名"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">邮箱</label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="请输入邮箱"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">密码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="请输入密码（至少6位）"
                  className="w-full pl-10 pr-12 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">确认密码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="请再次输入密码"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">验证码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={verificationCode}
                  onChange={(e) => setVerificationCode(e.target.value)}
                  placeholder="请输入邮箱验证码"
                  className="w-full pl-10 pr-32 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
                <button
                  type="button"
                  onClick={handleGetRegisterCode}
                  disabled={codeButtonDisabled || resendLoading}
                  className="absolute right-2 top-1/2 -translate-y-1/2 px-4 py-1.5 bg-gray-100 text-gray-600 rounded-lg hover:bg-gray-200 transition-colors text-sm disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {resendLoading ? '发送中...' : codeButtonText}
                </button>
              </div>
            </div>

            <button
              type="submit"
              className="w-full py-3 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors flex items-center justify-center gap-2"
            >
              <UserPlus className="w-5 h-5" />
              注册
            </button>
          </form>
        )}

        {showVerification && (
          <form onSubmit={handleVerify} className="space-y-4">
            <div className="p-4 bg-green-50 border border-green-200 rounded-lg">
              <div className="flex items-start gap-3">
                <CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="text-sm text-green-800 font-medium">注册成功！</p>
                  <p className="text-xs text-green-600 mt-1">{verificationMessage}</p>
                </div>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">验证码</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  value={verificationCode}
                  onChange={(e) => setVerificationCode(e.target.value)}
                  placeholder="请输入邮箱中的验证码"
                  className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 uppercase"
                />
              </div>
            </div>

            <button
              type="submit"
              className="w-full py-3 bg-green-500 text-white rounded-lg font-medium hover:bg-green-600 transition-colors flex items-center justify-center gap-2"
            >
              <CheckCircle className="w-5 h-5" />
              完成验证
            </button>

            <button
              type="button"
              onClick={handleResendVerification}
              disabled={resendLoading}
              className="w-full py-3 bg-gray-100 text-gray-600 rounded-lg font-medium hover:bg-gray-200 transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
            >
              {resendLoading ? (
                <>
                  <RefreshCw className="w-5 h-5 animate-spin" />
                  发送中...
                </>
              ) : (
                <>
                  <RefreshCw className="w-5 h-5" />
                  重新发送验证码
                </>
              )}
            </button>
          </form>
        )}

        <div className="mt-6 text-center space-y-2">
          {isLogin ? (
            <>
              <p className="text-sm text-gray-500">
                还没有账户？{' '}
                <button
                  onClick={() => setIsLogin(false)}
                  className="text-blue-600 hover:text-blue-700 font-medium"
                >
                  立即注册
                </button>
              </p>
              <p className="text-sm text-gray-500">
                忘记密码？{' '}
                <Link
                  to="/forgot-password"
                  className="text-blue-600 hover:text-blue-700 font-medium"
                >
                  找回密码
                </Link>
              </p>
            </>
          ) : (
            <p className="text-sm text-gray-500">
              已有账户？{' '}
              <button
                onClick={() => setIsLogin(true)}
                className="text-blue-600 hover:text-blue-700 font-medium"
              >
                立即登录
              </button>
            </p>
          )}
        </div>

      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import {
  Menu, Plus, Trash2, Edit, GripVertical, Save, X, ChevronDown,
  ChevronRight, ExternalLink, Globe, FileText, FolderOpen, Tag,
  Link as LinkIcon, Home, Eye, EyeOff, Settings, ArrowUp, ArrowDown
} from 'lucide-react';
import Modal, { Toast } from '../components/Modal';
import { useModal, useToast } from '../hooks/useModal';
import { useData } from '../contexts/DataContext';

export default function Menus() {
  const { confirm, alert, isOpen: isModalOpen, modalConfig, closeModal } = useModal();
  const { showToast, isOpen: isToastOpen, toastConfig, closeToast } = useToast();
  const { menus, posts, pages, categories, tags, createMenu, updateMenu, deleteMenu } = useData();
  const [selectedMenu, setSelectedMenu] = useState(null);
  const [editingItem, setEditingItem] = useState(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [addItemType, setAddItemType] = useState('custom');
  const [draggedItem, setDraggedItem] = useState(null);
  // 这三个状态原来声明在 renderAddModal 函数体里（一个普通函数，不是组件）。
  // 它只在 showAddModal 为真时被调用，于是每次开关弹窗都会改变 hook 数量，
  // React 会抛出「Rendered more hooks than during the previous render」。
  // 提到组件顶层即可。
  const [customTitle, setCustomTitle] = useState('');
  const [customUrl, setCustomUrl] = useState('');
  const [selectedId, setSelectedId] = useState('');

  useEffect(() => {
    const menusArray = menus || [];
    if (menusArray.length > 0 && !selectedMenu) {
      setSelectedMenu(menusArray[0]);
    }
  }, [menus, selectedMenu]);

  const handleSelectMenu = (menu) => {
    setSelectedMenu(menu);
    setEditingItem(null);
  };

  const handleAddMenu = async () => {
    const newMenuData = {
      title: '新菜单',
      location: 'header',
      items: [],
    };
    try {
      const newMenu = await createMenu(newMenuData);
      setSelectedMenu(newMenu);
    } catch (e) {
      showToast('创建菜单功能暂未实现', 'warning');
    }
  };

  const handleDeleteMenu = async (menuId) => {
    const confirmed = await confirm({
      title: '确认删除',
      message: '确定要删除这个菜单吗？',
    });
    if (confirmed) {
      try {
        await deleteMenu(menuId);
        showToast('菜单删除成功', 'success');
        if (selectedMenu?.id === menuId) {
          const otherMenu = menus.find(m => m.id !== menuId);
          setSelectedMenu(otherMenu || null);
        }
      } catch (e) {
        showToast('删除菜单功能暂未实现', 'warning');
      }
    }
  };

  const handleUpdateMenu = async (field, value) => {
    if (!selectedMenu) return;
    try {
      await updateMenu(selectedMenu.id, { [field]: value });
      setSelectedMenu({ ...selectedMenu, [field]: value });
    } catch (e) {
      showToast('更新菜单功能暂未实现', 'warning');
    }
  };

  const handleAddItem = (type, data) => {
    if (!selectedMenu) return;
    showToast('添加菜单项功能暂未实现', 'warning');
    setShowAddModal(false);
  };

  const handleEditItem = (item) => {
    setEditingItem({ ...item });
  };

  const handleSaveItem = () => {
    if (!selectedMenu || !editingItem) return;
    showToast('编辑菜单项功能暂未实现', 'warning');
    setEditingItem(null);
  };

  const handleDeleteItem = async (itemId) => {
    if (!selectedMenu) return;
    const confirmed = await confirm({
      title: '确认删除',
      message: '确定要删除这个菜单项吗？',
    });
    if (confirmed) {
      showToast('删除菜单项功能暂未实现', 'warning');
    }
  };

  const handleToggleItem = (itemId) => {
    showToast('切换菜单项功能暂未实现', 'warning');
  };

  const handleDragStart = (e, item) => {
    setDraggedItem(item);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  const handleDrop = (e, targetItem) => {
    e.preventDefault();
    showToast('拖拽排序功能暂未实现', 'warning');
    setDraggedItem(null);
  };

  const handleMoveItem = (itemId, direction) => {
    showToast('移动菜单项功能暂未实现', 'warning');
  };

  const renderAddModal = () => {
    return (
      <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
        <div className="bg-white dark:bg-gray-800 rounded-xl w-full max-w-lg p-6">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">添加菜单项</h3>
            <button onClick={() => { setShowAddModal(false); setAddItemType('custom'); }} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded">
              <X className="w-5 h-5 text-gray-500" />
            </button>
          </div>

          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">链接类型</label>
            <div className="grid grid-cols-5 gap-2">
              {[
                { type: 'custom', icon: LinkIcon, label: '自定义' },
                { type: 'post', icon: FileText, label: '文章' },
                { type: 'page', icon: FolderOpen, label: '页面' },
                { type: 'category', icon: FolderOpen, label: '分类' },
                { type: 'tag', icon: Tag, label: '标签' },
              ].map(item => (
                <button
                  key={item.type}
                  onClick={() => setAddItemType(item.type)}
                  className={`flex flex-col items-center gap-1 p-3 rounded-lg border-2 transition-colors ${
                    addItemType === item.type
                      ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/30'
                      : 'border-gray-200 dark:border-gray-600 hover:border-gray-300'
                  }`}
                >
                  <item.icon className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  <span className="text-xs text-gray-600 dark:text-gray-400">{item.label}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-6">
            {addItemType === 'custom' && (
              <>
                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">标题</label>
                  <input
                    type="text"
                    value={customTitle}
                    onChange={(e) => setCustomTitle(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    placeholder="菜单项标题"
                  />
                </div>
                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">URL</label>
                  <input
                    type="text"
                    value={customUrl}
                    onChange={(e) => setCustomUrl(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    placeholder="/about 或 https://example.com"
                  />
                </div>
              </>
            )}

            {addItemType === 'post' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">选择文章</label>
                <select
                  value={selectedId}
                  onChange={(e) => setSelectedId(Number(e.target.value) || null)}
                  className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                >
                  <option value="">请选择文章</option>
                  {posts.filter(p => p.status === 'published').map(post => (
                    <option key={post.id} value={post.id}>{post.title}</option>
                  ))}
                </select>
              </div>
            )}

            {addItemType === 'page' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">选择页面</label>
                <select
                  value={selectedId}
                  onChange={(e) => setSelectedId(Number(e.target.value) || null)}
                  className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                >
                  <option value="">请选择页面</option>
                  {pages.filter(p => p.status === 'published').map(page => (
                    <option key={page.id} value={page.id}>{page.title}</option>
                  ))}
                </select>
              </div>
            )}

            {addItemType === 'category' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">选择分类</label>
                <select
                  value={selectedId}
                  onChange={(e) => setSelectedId(Number(e.target.value) || null)}
                  className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                >
                  <option value="">请选择分类</option>
                  {categories.map(category => (
                    <option key={category.id} value={category.id}>{category.name}</option>
                  ))}
                </select>
              </div>
            )}

            {addItemType === 'tag' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">选择标签</label>
                <select
                  value={selectedId}
                  onChange={(e) => setSelectedId(Number(e.target.value))}
                  className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                >
                  <option value="">请选择标签</option>
                  {tags.map(tag => (
                    <option key={tag.id} value={tag.id}>{tag.name}</option>
                  ))}
                </select>
              </div>
            )}
          </div>

          <div className="flex justify-end gap-3">
            <button
              onClick={() => { setShowAddModal(false); setAddItemType('custom'); }}
              className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
            >
              取消
            </button>
            <button
              onClick={() => {
                if (addItemType === 'custom') {
                  handleAddItem('custom', { title: customTitle, url: customUrl });
                } else {
                  handleAddItem(addItemType, { id: selectedId });
                }
              }}
              className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
            >
              添加
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderEditModal = () => {
    if (!editingItem) return null;

    return (
      <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
        <div className="bg-white dark:bg-gray-800 rounded-xl w-full max-w-lg p-6">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">编辑菜单项</h3>
            <button onClick={() => setEditingItem(null)} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded">
              <X className="w-5 h-5 text-gray-500" />
            </button>
          </div>

          <div className="space-y-4 mb-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">标题</label>
              <input
                type="text"
                value={editingItem.title}
                onChange={(e) => setEditingItem({ ...editingItem, title: e.target.value })}
                className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">URL</label>
              <input
                type="text"
                value={editingItem.url}
                onChange={(e) => setEditingItem({ ...editingItem, url: e.target.value })}
                className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">打开方式</label>
              <select
                value={editingItem.target}
                onChange={(e) => setEditingItem({ ...editingItem, target: e.target.value })}
                className="w-full px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
              >
                <option value="_self">当前窗口</option>
                <option value="_blank">新窗口</option>
              </select>
            </div>
          </div>

          <div className="flex justify-end gap-3">
            <button
              onClick={() => setEditingItem(null)}
              className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
            >
              取消
            </button>
            <button
              onClick={handleSaveItem}
              className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
            >
              保存
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <>
      <div className="p-6">
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">菜单管理</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">管理网站导航菜单</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* 左侧菜单列表 */}
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-semibold text-gray-900 dark:text-white">菜单</h2>
            <button
              onClick={handleAddMenu}
              className="p-1.5 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
            >
              <Plus className="w-4 h-4" />
            </button>
          </div>

          <div className="space-y-2">
            {(menus || []).map(menu => (
              <div
                key={menu.id}
                onClick={() => handleSelectMenu(menu)}
                className={`flex items-center justify-between p-3 rounded-lg cursor-pointer transition-colors ${
                  selectedMenu?.id === menu.id
                    ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                    : 'hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-300'
                }`}
              >
                <div className="flex items-center gap-3">
                  <Menu className="w-5 h-5" />
                  <div>
                    <div className="font-medium">{menu.title}</div>
                    <div className="text-xs text-gray-400">
                      {menu.location === 'header' ? '头部导航' : '页脚导航'} · {(menu.items || []).length} 项
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-1">
                  <button
                    onClick={(e) => { e.stopPropagation(); handleDeleteMenu(menu.id); }}
                    className="p-1 hover:bg-red-100 dark:hover:bg-red-900/30 text-red-500 rounded"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* 右侧菜单编辑器 */}
        <div className="lg:col-span-3 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          {selectedMenu ? (
            <>
              {/* 菜单设置 */}
              <div className="p-6 border-b border-gray-100 dark:border-gray-700">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-lg font-semibold text-gray-900 dark:text-white">{selectedMenu.title}</h2>
                  <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2">
                      <span className="text-sm text-gray-500">菜单位置</span>
                      <select
                        value={selectedMenu.location}
                        onChange={(e) => handleUpdateMenu('location', e.target.value)}
                        className="px-3 py-1.5 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm"
                      >
                        <option value="header">头部导航</option>
                        <option value="footer">页脚导航</option>
                      </select>
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-4">
                  <input
                    type="text"
                    value={selectedMenu.title}
                    onChange={(e) => handleUpdateMenu('title', e.target.value)}
                    className="flex-1 px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    placeholder="菜单名称"
                  />
                  <button
                    onClick={() => setShowAddModal(true)}
                    className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 flex items-center gap-2"
                  >
                    <Plus className="w-4 h-4" />
                    添加项目
                  </button>
                </div>
              </div>

              {/* 预览位置 */}
              <div className="px-6 py-3 bg-gray-50 dark:bg-gray-900/50 border-b border-gray-100 dark:border-gray-700">
                <div className="flex items-center gap-2 text-sm text-gray-500">
                  <Eye className="w-4 h-4" />
                  <span>预览位置：</span>
                  <span className="px-2 py-0.5 bg-white dark:bg-gray-700 rounded border border-gray-200 dark:border-gray-600">
                    {selectedMenu.location === 'header' ? '头部导航' : '页脚导航'}
                  </span>
                </div>
              </div>

              {/* 菜单项列表 */}
              <div className="p-6">
                {(selectedMenu?.items || []).length === 0 ? (
                  <div className="text-center py-12">
                    <Menu className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                    <p className="text-gray-500 dark:text-gray-400">暂无菜单项</p>
                    <button
                      onClick={() => setShowAddModal(true)}
                      className="mt-4 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
                    >
                      添加第一个菜单项
                    </button>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {(selectedMenu?.items || [])
                      .sort((a, b) => (a.order || 0) - (b.order || 0))
                      .map((item, index) => (
                        <div
                          key={item.id}
                          draggable
                          onDragStart={(e) => handleDragStart(e, item)}
                          onDragOver={handleDragOver}
                          onDrop={(e) => handleDrop(e, item)}
                          className={`flex items-center gap-3 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-100 dark:border-gray-700 ${
                            draggedItem?.id === item.id ? 'opacity-50' : ''
                          } ${!item.enabled ? 'opacity-50' : ''}`}
                        >
                          <div className="cursor-move text-gray-400 hover:text-gray-600">
                            <GripVertical className="w-5 h-5" />
                          </div>

                          <button
                            onClick={() => handleMoveItem(item.id, 'up')}
                            disabled={index === 0}
                            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:opacity-30"
                          >
                            <ArrowUp className="w-4 h-4 text-gray-500" />
                          </button>

                          <button
                            onClick={() => handleMoveItem(item.id, 'down')}
                            disabled={index === (selectedMenu?.items || []).length - 1}
                            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:opacity-30"
                          >
                            <ArrowDown className="w-4 h-4 text-gray-500" />
                          </button>

                          <div className="flex-1">
                            <div className="font-medium text-gray-900 dark:text-white">{item.title}</div>
                            <div className="text-xs text-gray-500 flex items-center gap-2">
                              <span>{item.url}</span>
                              {item.target === '_blank' && (
                                <span className="px-1 py-0.5 bg-gray-200 dark:bg-gray-700 rounded text-xs">新窗口</span>
                              )}
                            </div>
                          </div>

                          <button
                            onClick={() => handleToggleItem(item.id)}
                            className={`p-1.5 rounded-lg ${
                              item.enabled
                                ? 'bg-green-100 dark:bg-green-900/30 text-green-600 hover:bg-green-200'
                                : 'bg-gray-200 dark:bg-gray-700 text-gray-500 hover:bg-gray-300'
                            }`}
                          >
                            {item.enabled ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                          </button>

                          <button
                            onClick={() => handleEditItem(item)}
                            className="p-1.5 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-lg"
                          >
                            <Edit className="w-4 h-4 text-gray-500" />
                          </button>

                          <button
                            onClick={() => handleDeleteItem(item.id)}
                            className="p-1.5 hover:bg-red-100 dark:hover:bg-red-900/30 text-red-500 rounded-lg"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ))}
                  </div>
                )}
              </div>
            </>
          ) : (
            <div className="text-center py-20">
              <Menu className="w-16 h-16 text-gray-300 mx-auto mb-4" />
              <p className="text-gray-500 dark:text-gray-400">选择一个菜单进行编辑</p>
              <button
                onClick={handleAddMenu}
                className="mt-4 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
              >
                创建新菜单
              </button>
            </div>
          )}
        </div>
      </div>

      {showAddModal && renderAddModal()}
      {editingItem && renderEditModal()}

      <Modal
        isOpen={isModalOpen}
        onClose={closeModal}
        title={modalConfig.title}
        message={modalConfig.message}
        type={modalConfig.type}
        confirmText={modalConfig.confirmText}
        cancelText={modalConfig.cancelText}
        onConfirm={modalConfig.onConfirm}
        showCancel={modalConfig.showCancel}
      />

      <Toast
        isOpen={isToastOpen}
        message={toastConfig.message}
        type={toastConfig.type}
        onClose={closeToast}
        duration={toastConfig.duration}
      />
    </div>
    </>
  );
}

import { useState, useEffect } from 'react';
import { 
  Bell, 
  BellOff, 
  CheckCircle, 
  AlertCircle, 
  Info, 
  Trash2, 
  Clock,
  Filter,
  Search,
  RefreshCw,
  Mail,
  UserPlus,
  FileText,
  Settings,
  Server,
  AlertTriangle,
  MessageSquare
} from 'lucide-react';
import { useModal, useToast } from '../hooks/useModal';
import { useData } from '../contexts/DataContext';
import { notificationsAPI } from '../services/api';

const notificationTypeConfig = {
  register_request: { icon: UserPlus, color: 'bg-blue-100 text-blue-700', label: '注册请求' },
  post_created: { icon: FileText, color: 'bg-green-100 text-green-700', label: '新文章' },
  comment: { icon: MessageSquare, color: 'bg-purple-100 text-purple-700', label: '新评论' },
  system: { icon: Server, color: 'bg-gray-100 text-gray-700', label: '系统日志' },
  error: { icon: AlertTriangle, color: 'bg-red-100 text-red-700', label: '错误' },
  warning: { icon: AlertCircle, color: 'bg-yellow-100 text-yellow-700', label: '警告' },
  info: { icon: Info, color: 'bg-blue-100 text-blue-700', label: '信息' },
  mail: { icon: Mail, color: 'bg-cyan-100 text-cyan-700', label: '邮件' },
  settings: { icon: Settings, color: 'bg-indigo-100 text-indigo-700', label: '设置' },
};

export default function Notifications() {
  const { confirm, isOpen: isModalOpen, modalConfig, closeModal } = useModal();
  const { showToast, isOpen: isToastOpen, toastConfig, closeToast } = useToast();
  const { notifications, getNotifications, markNotificationAsRead, deleteNotification } = useData();
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState('all');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    loadNotifications();
  }, []);

  const loadNotifications = async () => {
    setIsLoading(true);
    try {
      await getNotifications();
    } catch (error) {
      console.error('加载通知失败:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRefresh = () => {
    loadNotifications();
  };

  const handleMarkAsRead = async (id) => {
    try {
      await markNotificationAsRead(id);
      showToast('已标记为已读', 'success');
    } catch (error) {
      showToast('操作失败', 'error');
    }
  };

  const handleDelete = async (id, title) => {
    const confirmed = await confirm({
      title: '确认删除',
      message: `确定要删除这条通知吗？`,
    });
    if (confirmed) {
      try {
        await deleteNotification(id);
        showToast('删除成功', 'success');
      } catch (error) {
        showToast('删除失败', 'error');
      }
    }
  };

  const handleMarkAllAsRead = async () => {
    try {
      await notificationsAPI.markAllAsRead();
      await getNotifications();
      showToast('已全部标记为已读', 'success');
    } catch (error) {
      showToast('操作失败', 'error');
    }
  };

  const handleClearAll = async () => {
    const confirmed = await confirm({
      title: '确认清空',
      message: '确定要清空所有通知吗？此操作不可撤销。',
    });
    if (confirmed) {
      try {
        await notificationsAPI.clearAll();
        await getNotifications();
        showToast('已清空所有通知', 'success');
      } catch (error) {
        showToast('操作失败', 'error');
      }
    }
  };

  const filteredNotifications = notifications.filter(notif => {
    const matchesSearch = notif.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         notif.message.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesType = filterType === 'all' || notif.type === filterType;
    return matchesSearch && matchesType;
  });

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);

    if (minutes < 1) return '刚刚';
    if (minutes < 60) return `${minutes}分钟前`;
    if (hours < 24) return `${hours}小时前`;
    if (days < 7) return `${days}天前`;
    return date.toLocaleString('zh-CN');
  };

  const types = ['all', ...new Set(notifications.map(n => n.type))];

  return (
    <div className="p-6">
      <div className="mb-6 flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">通知中心</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">查看系统通知、用户活动和日志信息</p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={handleRefresh}
            disabled={isLoading}
            className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg font-medium hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors flex items-center gap-2 disabled:opacity-50"
          >
            <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
            刷新
          </button>
          <button
            onClick={handleMarkAllAsRead}
            className="px-4 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors flex items-center gap-2"
          >
            <CheckCircle className="w-4 h-4" />
            全部已读
          </button>
          <button
            onClick={handleClearAll}
            className="px-4 py-2 bg-red-500 text-white rounded-lg font-medium hover:bg-red-600 transition-colors flex items-center gap-2"
          >
            <Trash2 className="w-4 h-4" />
            清空
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700">
          <div className="flex flex-col md:flex-row md:items-center gap-4">
            <div className="relative flex-1 max-w-md">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="搜索通知..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div className="flex items-center gap-2">
              <Filter className="w-4 h-4 text-gray-400" />
              <select
                value={filterType}
                onChange={(e) => setFilterType(e.target.value)}
                className="px-3 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="all">全部类型</option>
                {types.filter(t => t !== 'all').map(type => (
                  <option key={type} value={type}>
                    {notificationTypeConfig[type]?.label || type}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        <div className="p-4">
          {isLoading ? (
            <div className="py-12 text-center">
              <RefreshCw className="w-8 h-8 text-blue-500 animate-spin mx-auto mb-4" />
              <p className="text-gray-500">加载中...</p>
            </div>
          ) : filteredNotifications.length === 0 ? (
            <div className="py-12 text-center">
              {notifications.length === 0 ? (
                <>
                  <BellOff className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                  <p className="text-gray-500 dark:text-gray-400">暂无通知</p>
                  <p className="text-sm text-gray-400 mt-1">系统活动将在这里显示</p>
                </>
              ) : (
                <>
                  <Search className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                  <p className="text-gray-500 dark:text-gray-400">没有找到匹配的通知</p>
                  <p className="text-sm text-gray-400 mt-1">尝试使用不同的关键词搜索</p>
                </>
              )}
            </div>
          ) : (
            <div className="space-y-3">
              {filteredNotifications.map(notification => {
                const config = notificationTypeConfig[notification.type] || notificationTypeConfig.info;
                const Icon = config.icon;

                return (
                  <div
                    key={notification.id}
                    className={`p-4 rounded-xl border transition-all hover:shadow-sm ${
                      notification.is_read
                        ? 'bg-gray-50 dark:bg-gray-700/50 border-gray-100 dark:border-gray-600'
                        : 'bg-white dark:bg-gray-800 border-blue-200 dark:border-blue-700'
                    }`}
                  >
                    <div className="flex items-start gap-4">
                      <div className={`w-10 h-10 rounded-lg ${config.color} flex items-center justify-center flex-shrink-0`}>
                        <Icon className="w-5 h-5" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-medium text-gray-900 dark:text-white">
                            {notification.title}
                          </h3>
                          {!notification.is_read && (
                            <span className="w-2 h-2 bg-blue-500 rounded-full" />
                          )}
                        </div>
                        <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
                          {notification.message}
                        </p>
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-4 text-xs text-gray-400">
                            <span className="flex items-center gap-1">
                              <Clock className="w-3 h-3" />
                              {formatDate(notification.created_at)}
                            </span>
                            <span className={`px-2 py-0.5 rounded-full text-xs ${config.color}`}>
                              {config.label}
                            </span>
                          </div>
                          <div className="flex items-center gap-2">
                            {!notification.is_read && (
                              <button
                                onClick={() => handleMarkAsRead(notification.id)}
                                className="px-3 py-1 text-sm text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                              >
                                标记已读
                              </button>
                            )}
                            <button
                              onClick={() => handleDelete(notification.id, notification.title)}
                              className="px-3 py-1 text-sm text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                            >
                              删除
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      <div className="mt-6 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
            <Server className="w-5 h-5 text-gray-500" />
            系统日志摘要
          </h2>
        </div>
        <div className="p-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-xl">
              <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">
                {notifications.length}
              </div>
              <div className="text-sm text-gray-600 dark:text-gray-400 mt-1">总通知数</div>
            </div>
            <div className="p-4 bg-green-50 dark:bg-green-900/20 rounded-xl">
              <div className="text-2xl font-bold text-green-600 dark:text-green-400">
                {notifications.filter(n => n.is_read).length}
              </div>
              <div className="text-sm text-gray-600 dark:text-gray-400 mt-1">已读</div>
            </div>
            <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 rounded-xl">
              <div className="text-2xl font-bold text-yellow-600 dark:text-yellow-400">
                {notifications.filter(n => !n.is_read).length}
              </div>
              <div className="text-sm text-gray-600 dark:text-gray-400 mt-1">未读</div>
            </div>
            <div className="p-4 bg-red-50 dark:bg-red-900/20 rounded-xl">
              <div className="text-2xl font-bold text-red-600 dark:text-red-400">
                {notifications.filter(n => n.type === 'error').length}
              </div>
              <div className="text-sm text-gray-600 dark:text-gray-400 mt-1">错误日志</div>
            </div>
          </div>
        </div>
      </div>

      <div className="mt-6 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
            <Bell className="w-5 h-5 text-gray-500" />
            通知类型统计
          </h2>
        </div>
        <div className="p-4">
          <div className="flex flex-wrap gap-3">
            {types.filter(t => t !== 'all').map(type => {
              const config = notificationTypeConfig[type] || notificationTypeConfig.info;
              const count = notifications.filter(n => n.type === type).length;
              if (count === 0) return null;
              return (
                <div
                  key={type}
                  className={`px-4 py-2 rounded-lg ${config.color} flex items-center gap-2`}
                >
                  {config.label}: {count}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { ArrowLeft, Save, Eye, Calendar, Tag, Pin, Clock, History, RotateCcw, Trash2, X } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';
import RichTextEditor from '../components/RichTextEditor';
import ContentPreview from '../components/ContentPreview';
import Modal, { Toast } from '../components/Modal';
import { useModal, useToast } from '../hooks/useModal';
import { useData } from '../contexts/DataContext';
import { sanitizeHtml } from '../lib/sanitize';

export default function PostEditor() {
  const { confirm, alert, isOpen: isModalOpen, modalConfig, closeModal } = useModal();
  const { showToast, isOpen: isToastOpen, toastConfig, closeToast } = useToast();
  const { id } = useParams();
  // 原来保存走 props.onSave 回调，现在页面自取 Context 的语义化方法
  const { posts, getPost, categories, createPost, updatePost } = useData();
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [excerpt, setExcerpt] = useState('');
  const [category, setCategory] = useState('');
  const [tags, setTags] = useState([]);
  const [newTag, setNewTag] = useState('');
  const [showPreview, setShowPreview] = useState(false);
  const [isPublished, setIsPublished] = useState(false);
  const [postId, setPostId] = useState(null);
  const [isSticky, setIsSticky] = useState(false);
  const [publishType, setPublishType] = useState('now');
  const [publishDate, setPublishDate] = useState('');
  const [showRevisions, setShowRevisions] = useState(false);
  const [selectedRevision, setSelectedRevision] = useState(null);
  const [revisions, setRevisions] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    if (id) {
      const postIdNum = parseInt(id, 10);
      
      const fetchedPost = posts.find(p => {
        const postId = typeof p.id === 'string' ? parseInt(p.id, 10) : p.id;
        return postId === postIdNum;
      });
      
      if (fetchedPost) {
        setPostId(fetchedPost.id);
        setTitle(fetchedPost.title || '');
        setContent(fetchedPost.content || '');
        setExcerpt(fetchedPost.excerpt || '');
        setCategory(fetchedPost.category || categories[0]);
        setTags(fetchedPost.tags || []);
        setIsPublished(fetchedPost.status === 'published');
        setIsSticky(fetchedPost.sticky || false);
        if (fetchedPost.status === 'future') {
          setPublishType('scheduled');
          setPublishDate(fetchedPost.publishDate || '');
        }
      } else {
        // 本地列表里找不到这篇文章：可能是文章还没加载完，或者链接指向了不存在的 id。
        // 原来这里只打一行 console.log 就结束了，用户看到的是一个空白编辑器，
        // 完全不知道发生了什么。实际上面的 useEffect 会在 posts 加载完后重试。
      }
    }
  }, [id, posts]);

  const handleAddTag = (e) => {
    if (e.key === 'Enter' && newTag.trim()) {
      e.preventDefault();
      if (!tags.includes(newTag.trim())) {
        setTags([...tags, newTag.trim()]);
      }
      setNewTag('');
    }
  };

  const handleRemoveTag = (tagToRemove) => {
    setTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const createRevisionIfNeeded = () => {
    // 修订功能暂未实现
  };

  // 原来保存走 props.onSave 回调，现在页面自取 Context，成功后再跳转列表
  const handleSave = async (data) => {
    try {
      if (data.id) {
        await updatePost(data.id, data);
      } else {
        await createPost(data);
      }
      showToast('文章已保存', 'success');
      navigate('/admin/posts');
    } catch (err) {
      showToast(err.message || '保存失败', 'error');
    }
  };

  const handleSaveDraft = async () => {
    createRevisionIfNeeded();
    const postData = {
      title: title || '无标题',
      content,
      excerpt: excerpt || content.replace(/<[^>]*>/g, '').slice(0, 100) + '...',
      status: 'draft',
      publishDate: null,
      category,
      tags,
      sticky: isSticky,
      author: 'admin',
    };

    await handleSave({ ...postData, id: postId });
  };

  const handlePublish = async () => {
    if (!title.trim()) {
      await alert('请输入文章标题', 'warning');
      return;
    }
    if (!content.trim()) {
      await alert('请输入文章内容', 'warning');
      return;
    }
    if (publishType === 'scheduled' && !publishDate) {
      await alert('请选择定时发布时间', 'warning');
      return;
    }

    createRevisionIfNeeded();
    const postData = {
      title,
      content,
      excerpt: excerpt || content.replace(/<[^>]*>/g, '').slice(0, 100) + '...',
      status: publishType === 'scheduled' ? 'future' : 'published',
      publishDate: publishType === 'scheduled' ? publishDate : null,
      category,
      tags,
      sticky: isSticky,
      author: 'admin',
    };

    await handleSave({ ...postData, id: postId });
  };

  const handleRestoreRevision = async (revision) => {
    const confirmed = await confirm({
      title: '确认恢复',
      message: '确定要恢复到该修订版本吗？',
    });
    if (confirmed) {
      setTitle(revision.title);
      setContent(revision.content);
      setExcerpt(revision.excerpt);
      setSelectedRevision(null);
      setShowRevisions(false);
      showToast('修订功能暂未实现', 'warning');
    }
  };

  const handleCancelClick = () => {
    navigate('/admin/posts');
  };

  return (
    <>
      <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <button
            onClick={handleCancelClick}
            className="p-2 text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
              {postId ? '编辑文章' : '新建文章'}
            </h1>
            <p className="text-gray-500 dark:text-gray-400 mt-1">创建精彩内容，分享您的故事</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {postId && (
            <button
              onClick={() => setShowRevisions(true)}
              className="px-4 py-2 border border-gray-200 dark:border-gray-600 text-gray-700 dark:text-gray-300 rounded-lg font-medium hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors flex items-center gap-2"
            >
              <History className="w-4 h-4" />
              修订
            </button>
          )}
          <button
            onClick={() => setShowPreview(true)}
            className="px-4 py-2 border border-gray-200 dark:border-gray-600 text-gray-700 dark:text-gray-300 rounded-lg font-medium hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors flex items-center gap-2"
          >
            <Eye className="w-4 h-4" />
            预览
          </button>
          <button
            onClick={handleSaveDraft}
            className="px-4 py-2 border border-gray-200 dark:border-gray-600 text-gray-700 dark:text-gray-300 rounded-lg font-medium hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors flex items-center gap-2"
          >
            <Save className="w-4 h-4" />
            保存草稿
          </button>
          <button
            onClick={handlePublish}
            className="px-4 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors flex items-center gap-2"
          >
            <Save className="w-4 h-4" />
            {isPublished ? '更新发布' : '发布'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="输入文章标题..."
              className="w-full text-2xl font-bold text-gray-900 dark:text-white border-none focus:outline-none focus:ring-0 mb-6 bg-transparent"
            />
            
            <RichTextEditor value={content} onChange={setContent} />
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-4">文章设置</h3>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">分类</label>
                <select
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">选择分类</option>
                  {(categories || []).map((cat) => (
                    <option key={cat.id || cat.name} value={cat.name || cat}>{cat.name || cat}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">标签</label>
                <div className="flex gap-2 flex-wrap mb-2">
                  {tags.map((tag) => (
                    <span
                      key={tag}
                      className="inline-flex items-center gap-1 px-2 py-1 bg-blue-100 dark:bg-blue-900 text-blue-700 dark:text-blue-300 rounded-full text-sm"
                    >
                      {tag}
                      <button onClick={() => handleRemoveTag(tag)} className="hover:text-blue-900 dark:hover:text-blue-100">
                        x
                      </button>
                    </span>
                  ))}
                </div>
                <div className="relative">
                  <Tag className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <input
                    type="text"
                    value={newTag}
                    onChange={(e) => setNewTag(e.target.value)}
                    onKeyDown={handleAddTag}
                    placeholder="输入标签后按回车添加"
                    className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg text-sm bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                  />
                </div>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-4">摘要</h3>
            <textarea
              value={excerpt}
              onChange={(e) => setExcerpt(e.target.value)}
              placeholder="文章摘要，将显示在文章列表中..."
              rows={4}
              className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white resize-none focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-4">发布信息</h3>
            <div className="space-y-3 text-sm text-gray-600 dark:text-gray-400">
              <div className="flex items-center gap-2">
                <Calendar className="w-4 h-4 text-gray-400" />
                <span>创建日期: {new Date().toISOString().split('T')[0]}</span>
              </div>
              <div className="flex items-center gap-2">
                <Calendar className="w-4 h-4 text-gray-400" />
                <span>更新日期: {new Date().toISOString().split('T')[0]}</span>
              </div>
              <div>
                <span>作者: admin</span>
              </div>
              <div className="flex items-center justify-between pt-2 border-t border-gray-100 dark:border-gray-700">
                <span>置顶文章</span>
                <button
                  onClick={() => setIsSticky(!isSticky)}
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                    isSticky ? 'bg-blue-500' : 'bg-gray-200 dark:bg-gray-600'
                  }`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      isSticky ? 'translate-x-6' : 'translate-x-1'
                    }`}
                  />
                </button>
              </div>
              <div className="pt-2 border-t border-gray-100 dark:border-gray-700">
                <span className={`inline-block px-2 py-1 rounded-full text-xs font-medium ${
                  publishType === 'scheduled' ? 'bg-purple-100 dark:bg-purple-900 text-purple-700 dark:text-purple-300' :
                  isPublished ? 'bg-green-100 dark:bg-green-900 text-green-700 dark:text-green-300' : 'bg-yellow-100 dark:bg-yellow-900 text-yellow-700 dark:text-yellow-300'
                }`}>
                  {publishType === 'scheduled' ? '定时发布' : isPublished ? '已发布' : '草稿'}
                </span>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 p-6">
            <h3 className="font-semibold text-gray-900 dark:text-white mb-4">发布选项</h3>
            <div className="space-y-4">
              <div className="flex items-center gap-3">
                <input
                  type="radio"
                  id="publishNow"
                  name="publishType"
                  checked={publishType === 'now'}
                  onChange={() => setPublishType('now')}
                  className="w-4 h-4 text-blue-500"
                />
                <label htmlFor="publishNow" className="text-sm text-gray-700 dark:text-gray-300">
                  立即发布
                </label>
              </div>
              <div className="flex items-center gap-3">
                <input
                  type="radio"
                  id="publishScheduled"
                  name="publishType"
                  checked={publishType === 'scheduled'}
                  onChange={() => setPublishType('scheduled')}
                  className="w-4 h-4 text-blue-500"
                />
                <label htmlFor="publishScheduled" className="text-sm text-gray-700 dark:text-gray-300">
                  定时发布
                </label>
              </div>
              {publishType === 'scheduled' && (
                <div className="pl-7">
                  <input
                    type="datetime-local"
                    value={publishDate}
                    onChange={(e) => setPublishDate(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {showPreview && (
        <ContentPreview
          content={content}
          title={title}
          onClose={() => setShowPreview(false)}
          type="article"
        />
      )}

      {showRevisions && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl max-w-4xl w-full max-h-[80vh] overflow-hidden">
            <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-700">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white">修订历史</h2>
              <button
                onClick={() => {
                  setShowRevisions(false);
                  setSelectedRevision(null);
                }}
                className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="flex h-[calc(80vh-140px)]">
              <div className="w-1/3 border-r border-gray-100 dark:border-gray-700 overflow-y-auto">
                {revisions.length > 0 ? (
                  <div className="divide-y divide-gray-100 dark:divide-gray-700">
                    {revisions.map((revision) => (
                      <button
                        key={revision.id}
                        onClick={() => setSelectedRevision(revision)}
                        className={`w-full p-4 text-left hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors ${
                          selectedRevision?.id === revision.id ? 'bg-blue-50 dark:bg-blue-900' : ''
                        }`}
                      >
                        <div className="text-sm font-medium text-gray-900 dark:text-white truncate">
                          {revision.title.substring(0, 30)}{revision.title.length > 30 ? '...' : ''}
                        </div>
                        <div className="text-xs text-gray-500 dark:text-gray-400 mt-1 flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {new Date(revision.createdAt).toLocaleString()}
                        </div>
                      </button>
                    ))}
                  </div>
                ) : (
                  <div className="p-6 text-center text-gray-500 dark:text-gray-400">
                    暂无修订记录
                  </div>
                )}
              </div>
              <div className="w-2/3 p-6 overflow-y-auto">
                {selectedRevision ? (
                  <div>
                    <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
                      {selectedRevision.title}
                    </h3>
                    <div className="text-sm text-gray-500 dark:text-gray-400 mb-4 flex items-center gap-2">
                      <span>修订时间: {new Date(selectedRevision.createdAt).toLocaleString()}</span>
                      <span>|</span>
                      <span>作者: {selectedRevision.author}</span>
                    </div>
                    <div className="prose dark:prose-invert max-w-none">
                      <div dangerouslySetInnerHTML={{ __html: sanitizeHtml(selectedRevision.content) }} />
                    </div>
                    <div className="mt-6 pt-4 border-t border-gray-100 dark:border-gray-700">
                      <button
                        onClick={() => handleRestoreRevision(selectedRevision)}
                        className="px-4 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors flex items-center gap-2"
                      >
                        <RotateCcw className="w-4 h-4" />
                        恢复到该版本
                      </button>
                    </div>
                  </div>
                ) : (
                  <div className="h-full flex items-center justify-center text-gray-500 dark:text-gray-400">
                    选择一个修订版本查看详情
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      <Modal
        isOpen={isModalOpen}
        onClose={closeModal}
        title={modalConfig.title}
        message={modalConfig.message}
        type={modalConfig.type}
        confirmText={modalConfig.confirmText}
        cancelText={modalConfig.cancelText}
        onConfirm={modalConfig.onConfirm}
        showCancel={modalConfig.showCancel}
      />

      <Toast
        isOpen={isToastOpen}
        message={toastConfig.message}
        type={toastConfig.type}
        onClose={closeToast}
        duration={toastConfig.duration}
      />
    </div>
    </>
  );
}

import { useState } from 'react';
import { Plus, Search, Filter, Edit, Trash2, Eye, Pin, Clock, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import Modal, { Toast } from '../components/Modal';
import { useModal, useToast } from '../hooks/useModal';
import { useData } from '../contexts/DataContext';

export default function Posts() {
  const { confirm, alert, isOpen: isModalOpen, modalConfig, closeModal } = useModal();
  const { showToast, isOpen: isToastOpen, toastConfig, closeToast } = useToast();
  // 原来靠 props 拿 posts / onDelete，现在页面自取 Context
  const { posts, updatePost, deletePost, settings, categories } = useData();
  const [searchQuery, setSearchQuery] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterCategory, setFilterCategory] = useState('all');
  const navigate = useNavigate();

  // 根据设置获取文章链接
  // 原来生成的是 /post/xxx，而前台路由注册的是 /posts/:id，
  // 路径对不上，管理员点"查看文章"必然落到 404。
  const getPostUrl = (post) => {
    const urlType = settings?.postUrlType || 'slug';
    return urlType === 'id' ? `/posts/${post.id}` : `/posts/${post.slug || post.id}`;
  };

  const sortedPosts = [...posts].sort((a, b) => {
    if (a.sticky && !b.sticky) return -1;
    if (!a.sticky && b.sticky) return 1;
    return new Date(b.updatedAt) - new Date(a.updatedAt);
  });

  const filteredPosts = sortedPosts.filter((post) => {
    const matchesSearch = post.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         post.excerpt.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesStatus = filterStatus === 'all' || post.status === filterStatus;
    const matchesCategory = filterCategory === 'all' || post.category === filterCategory;
    return matchesSearch && matchesStatus && matchesCategory;
  });

  const getStatusBadge = (status) => {
    if (status === 'published') {
      return <span className="px-2 py-1 text-xs font-medium bg-green-100 dark:bg-green-900 text-green-700 dark:text-green-300 rounded-full">已发布</span>;
    }
    if (status === 'future') {
      return <span className="px-2 py-1 text-xs font-medium bg-purple-100 dark:bg-purple-900 text-purple-700 dark:text-purple-300 rounded-full">定时发布</span>;
    }
    return <span className="px-2 py-1 text-xs font-medium bg-yellow-100 dark:bg-yellow-900 text-yellow-700 dark:text-yellow-300 rounded-full">草稿</span>;
  };

  const handleToggleSticky = async (post, e) => {
    e.stopPropagation();
    // 原来调用 postsAPI.update —— 但 postsAPI 是从 DataContext 解构出来的，
    // 而 Context 从未提供该成员，拿到的是 undefined，一点击就抛 TypeError。
    // 改用 Context 的语义化方法，顺带让本地状态同步更新。
    try {
      await updatePost(post.id, { sticky: !post.sticky });
      showToast(post.sticky ? '已取消置顶' : '已置顶', 'success');
    } catch (err) {
      showToast(err.message || '操作失败', 'error');
    }
  };

  const handleCancelScheduled = async (post, e) => {
    e.stopPropagation();
    const confirmed = await confirm({
      title: '确认取消',
      message: '确定要取消定时发布吗？',
    });
    if (confirmed) {
      try {
        await updatePost(post.id, { status: 'draft', publishDate: null });
        showToast('已取消定时发布', 'success');
      } catch (err) {
        showToast(err.message || '操作失败', 'error');
      }
    }
  };

  const handleEditPost = (post) => {
    navigate(`/admin/posts/${post.id}/edit`);
  };

  const handleNewPost = () => {
    navigate('/admin/posts/new');
  };

  // 原来删除走 props.onDelete 回调，现在页面自取 Context 的 deletePost
  const handleDelete = async (post) => {
    const confirmed = await confirm({ title: '确认删除', message: `确定要删除《${post.title}》吗？` });
    if (!confirmed) return;
    try {
      await deletePost(post.id);
      showToast('文章已删除', 'success');
    } catch (err) {
      showToast(err.message || '删除失败', 'error');
    }
  };

  return (
    <>
      <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">文章管理</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">管理您网站的所有文章内容</p>
        </div>
        <button
          onClick={handleNewPost}
          className="px-4 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors flex items-center gap-2"
        >
          <Plus className="w-4 h-4" />
          新建文章
        </button>
      </div>

      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
        <div className="p-4 border-b border-gray-100 dark:border-gray-700">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                type="text"
                placeholder="搜索文章..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <div className="flex gap-3">
              <div className="relative">
                <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="pl-10 pr-8 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 appearance-none cursor-pointer"
                >
                  <option value="all">全部状态</option>
                  <option value="published">已发布</option>
                  <option value="draft">草稿</option>
                  <option value="future">定时发布</option>
                </select>
              </div>

              <select
                value={filterCategory}
                onChange={(e) => setFilterCategory(e.target.value)}
                className="px-4 py-2 border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 cursor-pointer"
              >
                <option value="all">全部分类</option>
                {(categories || []).map((cat) => (
                  <option key={cat.id || cat.name} value={cat.name || cat}>{cat.name || cat}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="bg-gray-50 dark:bg-gray-700">
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider w-12">置顶</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">标题</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">分类</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">作者</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">状态</th>
                <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">发布日期</th>
                <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {filteredPosts.map((post) => (
                <tr key={post.id} className="hover:bg-gray-50 dark:hover:bg-gray-700">
                  <td className="px-4 py-4">
                    <button
                      onClick={(e) => handleToggleSticky(post, e)}
                      className={`p-1.5 rounded-lg transition-colors ${
                        post.sticky
                          ? 'text-blue-500 bg-blue-50 dark:bg-blue-900 hover:bg-blue-100 dark:hover:bg-blue-800'
                          : 'text-gray-400 hover:text-blue-500 hover:bg-gray-100 dark:hover:bg-gray-700'
                      }`}
                      title={post.sticky ? '取消置顶' : '置顶'}
                    >
                      <Pin className="w-4 h-4" />
                    </button>
                  </td>
                  <td className="px-4 py-4">
                    <div>
                      <h3 className="font-medium text-gray-900 dark:text-white flex items-center gap-2">
                        {post.sticky && <Pin className="w-4 h-4 text-blue-500" />}
                        {post.title}
                      </h3>
                      <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 line-clamp-1">{post.excerpt}</p>
                    </div>
                  </td>
                  <td className="px-4 py-4">
                    <span className="px-2 py-1 text-xs font-medium bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-full">
                      {post.category}
                    </span>
                  </td>
                  <td className="px-4 py-4 text-sm text-gray-600 dark:text-gray-400">{post.author}</td>
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-2">
                      {getStatusBadge(post.status, post.publishDate)}
                      {post.status === 'future' && post.publishDate && (
                        <span className="text-xs text-gray-500 dark:text-gray-400 flex items-center gap-1">
                          <Clock className="w-3 h-3" />
                          {new Date(post.publishDate).toLocaleString()}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-4 py-4 text-sm text-gray-500 dark:text-gray-400">{post.createdAt}</td>
                  <td className="px-4 py-4">
                    <div className="flex items-center justify-end gap-2">
                      {post.status === 'future' && (
                        <button
                          onClick={(e) => handleCancelScheduled(post, e)}
                          className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900 rounded-lg transition-colors"
                          title="取消定时发布"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      )}
                      <button
                        onClick={() => window.open(getPostUrl(post), '_blank')}
                        className="p-2 text-gray-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900 rounded-lg transition-colors"
                        title="预览文章"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleEditPost(post)}
                        className="p-2 text-gray-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900 rounded-lg transition-colors"
                      >
                        <Edit className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleDelete(post)}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900 rounded-lg transition-colors"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {filteredPosts.length === 0 && (
          <div className="py-12 text-center">
            <p className="text-gray-500 dark:text-gray-400">没有找到匹配的文章</p>
          </div>
        )}
      </div>

      <Modal
        isOpen={isModalOpen}
        onClose={closeModal}
        title={modalConfig.title}
        message={modalConfig.message}
        type={modalConfig.type}
        confirmText={modalConfig.confirmText}
        cancelText={modalConfig.cancelText}
        onConfirm={modalConfig.onConfirm}
        showCancel={modalConfig.showCancel}
      />

      <Toast
        isOpen={isToastOpen}
        message={toastConfig.message}
        type={toastConfig.type}
        onClose={closeToast}
        duration={toastConfig.duration}
      />
    </div>
    </>
  );
}

import { useState, useEffect } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { Lock, ArrowLeft, Eye, EyeOff, CheckCircle } from 'lucide-react';
import PasswordStrength from '../components/PasswordStrength';

export default function ResetPassword() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [token, setToken] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [isValidating, setIsValidating] = useState(true);
  const [isValidToken, setIsValidToken] = useState(false);

  useEffect(() => {
    const tokenParam = searchParams.get('token');
    if (tokenParam) {
      setToken(tokenParam);
      // 模拟验证 token
      setTimeout(() => {
        setIsValidating(false);
        setIsValidToken(true);
      }, 1000);
    } else {
      setIsValidating(false);
      setIsValidToken(false);
    }
  }, [searchParams]);

  const handleResetPassword = () => {
    setError('');

    if (!newPassword) {
      setError('请输入新密码');
      return;
    }

    if (newPassword.length < 6) {
      setError('密码长度至少6位');
      return;
    }

    if (newPassword !== confirmPassword) {
      setError('两次输入的密码不一致');
      return;
    }

    // 模拟密码重置成功
    setSuccess('密码重置成功！');
    setTimeout(() => {
      navigate('/login');
    }, 2000);
  };

  if (isValidating) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8 text-center">
          <div className="w-16 h-16 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl flex items-center justify-center mx-auto mb-4">
            <span className="text-white text-2xl font-bold">H</span>
          </div>
          <p className="text-gray-500">正在验证链接...</p>
        </div>
      </div>
    );
  }

  if (!isValidToken) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8 text-center">
          <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Lock className="w-8 h-8 text-red-500" />
          </div>
          <h2 className="text-xl font-bold text-gray-900 mb-2">链接已失效</h2>
          <p className="text-gray-500 mb-6">
            此密码重置链接已过期或无效，请重新申请密码重置。
          </p>
          <Link
            to="/forgot-password"
            className="inline-block px-6 py-3 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors"
          >
            重新申请
          </Link>
          <div className="mt-4">
            <Link to="/login" className="text-sm text-blue-500 hover:text-blue-600">
              返回登录
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl flex items-center justify-center mx-auto mb-4">
            <span className="text-white text-2xl font-bold">H</span>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">HappyHome</h1>
          <p className="text-gray-500 mt-1">设置新密码</p>
        </div>

        <Link
          to="/login"
          className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-6"
        >
          <ArrowLeft className="w-4 h-4" />
          返回登录
        </Link>

        {error && (
          <div className="mb-4 p-3 bg-red-50 text-red-700 rounded-lg text-sm">
            {error}
          </div>
        )}

        {success && (
          <div className="mb-4 p-3 bg-green-50 text-green-700 rounded-lg text-sm flex items-center gap-2">
            <CheckCircle className="w-5 h-5" />
            {success}
          </div>
        )}

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">新密码</label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type={showPassword ? 'text' : 'password'}
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="请输入新密码"
                className="w-full pl-10 pr-12 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
              </button>
            </div>
            <PasswordStrength password={newPassword} />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">确认新密码</label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type={showPassword ? 'text' : 'password'}
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="请再次输入新密码"
                className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>

          <button
            onClick={handleResetPassword}
            className="w-full py-3 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-colors"
          >
            重置密码
          </button>
        </div>

        <div className="mt-6 text-center text-sm text-gray-500">
          <Link to="/login" className="text-blue-500 hover:text-blue-600">
            返回登录
          </Link>
        </div>
      </div>
    </div>
  );
}

