                  <div
                    key={theme.id}
                    onClick={() => handleActivate(theme)}
                    className={`relative rounded-xl overflow-hidden cursor-pointer transition-all hover:shadow-lg ${
                      theme.active ? 'ring-2 ring-blue-500' : ''
