import { Link } from 'react-router-dom';
import { FileText, Clock, User, Calendar, ExternalLink, Pin } from 'lucide-react';
import { useEffect } from 'react';
import { useData } from '../../contexts/DataContext';

export default function PublicHome() {
  // 原来靠 App.jsx 通过 props 下发数据，路由重构后页面自取 Context
  const { posts, pages, settings } = useData();
  const publishedPosts = posts.filter(post => post.status === 'published');
  const sortedPosts = [...publishedPosts].sort((a, b) => {
    if (a.sticky && !b.sticky) return -1;
    if (!a.sticky && b.sticky) return 1;
    return new Date(b.updatedAt) - new Date(a.updatedAt);
  });
  const recentPosts = sortedPosts.slice(0, 3);
  const publishedPages = (pages || []).filter(page => page.status === 'published');

  const siteName = settings?.siteName || 'HappyHome';
  const siteDescription = settings?.siteDescription || '一个功能强大、易于使用的建站平台';

  // SEO 设置
  const seo = settings?.seo || {};
  const siteUrl = settings?.siteUrl || '';

  // 更新页面 SEO 标签
  useEffect(() => {
    const title = seo.siteTitle || siteName;
    const description = seo.siteDescription || siteDescription;
    const keywords = seo.siteKeywords || '';
    const ogImage = seo.ogImage || '';

    // 设置文档标题
    document.title = title;

    // 更新 meta 标签
    const updateMeta = (name, content) => {
      let meta = document.querySelector(`meta[name="${name}"]`);
      if (!meta) {
        meta = document.createElement('meta');
        meta.setAttribute('name', name);
        document.head.appendChild(meta);
      }
      meta.setAttribute('content', content);
    };

    updateMeta('description', description);
    updateMeta('keywords', keywords);

    // Open Graph 标签
    const updateOg = (property, content) => {
      let meta = document.querySelector(`meta[property="${property}"]`);
      if (!meta) {
        meta = document.createElement('meta');
        meta.setAttribute('property', property);
        document.head.appendChild(meta);
      }
      meta.setAttribute('content', content);
    };

    updateOg('og:title', title);
    updateOg('og:description', description);
    updateOg('og:type', 'website');
    updateOg('og:url', siteUrl || window.location.origin);
    updateOg('og:site_name', siteName);
    if (ogImage) updateOg('og:image', ogImage);

    // Twitter Card 标签
    updateMeta('twitter:card', 'summary_large_image');
    updateMeta('twitter:title', title);
    updateMeta('twitter:description', description);
    if (ogImage) updateMeta('twitter:image', ogImage);

    // robots
    if (seo.noIndex) {
      updateMeta('robots', 'noindex, nofollow');
    } else {
      updateMeta('robots', seo.robots || 'index, follow');
    }

    // Canonical
    if (seo.canonical) {
      let link = document.querySelector('link[rel="canonical"]');
      if (!link) {
        link = document.createElement('link');
        link.setAttribute('rel', 'canonical');
        document.head.appendChild(link);
      }
      link.setAttribute('href', siteUrl || window.location.origin);
    }

    // 站长验证
    if (seo.bingVerification) {
      updateMeta('msvalidate.01', seo.bingVerification);
    }
    if (seo.baiduVerification) {
      updateMeta('baidu-site-verification', seo.baiduVerification);
    }

    return () => {
      document.title = siteName;
    };
  }, [seo, siteName, siteDescription, siteUrl]);

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Hero Section */}
      <section className="py-20 bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50">
        <div className="max-w-6xl mx-auto px-6 text-center">
          <h1 className="text-5xl font-extrabold text-gray-900 mb-6">
            欢迎来到 <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-purple-600">{siteName}</span>
          </h1>
          <p className="text-xl text-gray-600 max-w-3xl mx-auto mb-10">
            {siteDescription}。
            无需编程知识，即可拥有属于自己的网络空间。
          </p>
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
            <Link
              to="/posts"
              className="px-8 py-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl font-semibold hover:from-blue-700 hover:to-purple-700 transition-all shadow-lg hover:shadow-xl flex items-center gap-2"
            >
              浏览文章
              <FileText className="w-5 h-5" />
            </Link>
          </div>
        </div>
      </section>

      {/* Features */}
      <section className="py-16">
        <div className="max-w-6xl mx-auto px-6">
          <h2 className="text-3xl font-bold text-center text-gray-900 mb-12">
            我们的特色
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {[
              {
                icon: FileText,
                title: '内容管理',
                desc: '强大的富文本编辑器，支持多种内容格式，轻松创建和管理文章页面。'
              },
              {
                icon: Clock,
                title: '主题定制',
                desc: '丰富的主题选择，自定义颜色、字体和布局，打造独特的网站风格。'
              },
              {
                icon: User,
                title: '用户管理',
                desc: '完整的权限系统，支持多用户协作，灵活的角色分配。'
              }
            ].map((feature) => {
              const Icon = feature.icon;
              return (
                <div key={feature.title} className="bg-white rounded-2xl p-8 shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
                  <div className="w-14 h-14 bg-blue-100 rounded-xl flex items-center justify-center mb-4">
                    <Icon className="w-7 h-7 text-blue-600" />
                  </div>
                  <h3 className="text-xl font-bold text-gray-900 mb-2">{feature.title}</h3>
                  <p className="text-gray-600">{feature.desc}</p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Recent Posts */}
      {recentPosts.length > 0 && (
        <section className="py-16 bg-white">
          <div className="max-w-6xl mx-auto px-6">
            <div className="flex items-center justify-between mb-12">
              <h2 className="text-3xl font-bold text-gray-900">最新文章</h2>
              <Link
                to="/posts"
                className="flex items-center gap-2 text-blue-600 hover:text-blue-700 font-semibold"
              >
                查看全部
                <ExternalLink className="w-4 h-4" />
              </Link>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {recentPosts.map((post) => (
                <article key={post.id} className="group">
                  <Link to={`/posts/${post.id}`} className="block">
                    <div className="bg-gradient-to-br from-blue-400 to-purple-500 rounded-2xl aspect-video mb-4 group-hover:scale-[1.02] transition-transform overflow-hidden">
                      <div className="w-full h-full flex items-center justify-center text-white text-4xl opacity-30">
                        <FileText className="w-16 h-16" />
                      </div>
                    </div>
                    <div className="flex items-center gap-2 mb-2">
                      {post.sticky && (
                        <span className="px-2 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs font-medium flex items-center gap-1">
